"""Domain exception hierarchy for VIHAP (Vietnamese Hierarchical Address Parser)."""

from __future__ import annotations


class VihapError(Exception):
    """Base exception for all VIHAP domain errors."""


class VihapConfigError(VihapError, ValueError):
    """Raised when parser configuration options are invalid or conflicting."""


class VihapArtifactError(VihapError, FileNotFoundError):
    """Raised when required ontology or knowledge database artifacts are missing or corrupted."""


class VihapParsingError(VihapError):
    """Base exception for address parsing and structural decomposition failures."""


class AdminResolutionError(VihapParsingError):
    """Raised when administrative boundaries cannot be resolved or contain unresolvable contradictions."""

    def __init__(
        self,
        message: str,
        raw_address: str | None = None,
        candidate_admin: dict[str, str | None] | None = None,
    ) -> None:
        super().__init__(message)
        self.raw_address = raw_address
        self.candidate_admin = candidate_admin or {}


class InvalidAddressFormatError(VihapParsingError, ValueError):
    """Raised when an address input cannot be parsed due to invalid format or unsupported schema."""

    def __init__(self, message: str, raw_address: str | None = None) -> None:
        super().__init__(message)
        self.raw_address = raw_address


class VihapScoringError(VihapError, ValueError):
    """Raised when scoring evaluation fails due to incompatible inputs or dimensionality mismatch."""


__all__ = [
    "VihapError",
    "VihapConfigError",
    "VihapArtifactError",
    "VihapParsingError",
    "AdminResolutionError",
    "InvalidAddressFormatError",
    "VihapScoringError",
]
